<?php require __DIR__.'/_start.php'; ?>
<section class="customer-card"><h2>Ekip bildirimleri</h2><?php if(!$notifications): ?><p class="empty-state">Henüz bildirim yok.</p><?php endif ?><?php foreach($notifications as$n): ?><article class="customer-notification <?= $n['read_at']?'is-read':'' ?>"><div><p class="text-break"><?= e($n['message']) ?></p><small><?= e(date('d.m.Y H:i',strtotime($n['created_at']))) ?> · <?= $n['read_at']?'Okundu':'Okunmadı' ?></small><?php if($n['appointment_id']): ?><a class="d-block mt-2" href="<?= e(url('employee/appointments/detail?id='.$n['appointment_id'])) ?>">Randevuya git →</a><?php endif ?></div><?php if(!$n['read_at']): ?><form method="post" action="<?= e(url('employee/notifications/read')) ?>"><?= App\Core\Csrf::field() ?><input type="hidden" name="id" value="<?= (int)$n['id'] ?>"><button class="btn btn-sm btn-outline-dark" type="submit">Okundu işaretle</button></form><?php endif ?></article><?php endforeach ?></section>
<?php require __DIR__.'/_end.php'; ?>
